/** x where the monotone table ys (at xs) reaches y, between the rows; held to the ends. */
function invert(xs, ys, y) {
  const up = ys[ys.length - 1] >= ys[0];
  if (up ? y <= ys[0] : y >= ys[0]) return xs[0];
  for (let i = 1; i < ys.length; i++) {
    if (up ? y <= ys[i] : y >= ys[i]) return xs[i - 1] + ((xs[i] - xs[i - 1]) * (y - ys[i - 1])) / (ys[i] - ys[i - 1]);
  }
  return xs[xs.length - 1];
}
/** The row below x in xs and the fraction to the next: [i, t], held to the table. */
function cell(xs, x) {
  if (x <= xs[0]) return [0, 0];
  for (let i = 1; i < xs.length; i++) if (x <= xs[i]) return [i - 1, (x - xs[i - 1]) / (xs[i] - xs[i - 1])];
  return [xs.length - 2, 1];
}
const lerp = (a, b, t) => a + (b - a) * t;

/**
 * The weights that show an LV of edv and esv mL (the true volumes, before any foreshortening)
 * with walls wallMm thick on heart key: { size, wall, k, esSize }. The contraction k goes up to
 * the heart's own (k = 1): beyond it the systolic targets fold the walls (at an EF of 80% the
 * apex of the four-chamber view turns inside out). A smaller ESV keeps k = 1 and makes the LV
 * smaller at end-systole: the size weight goes from size at end-diastole to esSize at
 * end-systole, with the systolic weight. Each weight comes from the table above by linear
 * interpolation and is held to its range, so a heart that cannot reach a value shows the nearest
 * it can (the ischemic heart's akinetic LAD territory, say, limits its EF in a small LV).
 */
export function lvWeights(heart, edv, esv, wallMm) {
  const T = LV[heart] || LV.normal;
  const wall = invert(LV_WL, T.wall, wallMm);
  const [iw, tw] = cell(LV_WL, wall);
  const size = invert(LV_SZ, T.ed.map((row) => lerp(row[iw], row[iw + 1], tw)), edv);
  const [is, ts] = cell(LV_SZ, size);
  const at = (s, k) => lerp(T.es[s][iw][k], T.es[s][iw + 1][k], tw);
  const own = LV_K.indexOf(1);
  const es = LV_K.slice(0, own + 1).map((_, k) => lerp(at(is, k), at(is + 1, k), ts));
  // the contraction up to the heart's own, while the ESV still falls as k grows
  let n = 1;
  while (n < es.length && es[n] < es[n - 1]) n++;
  if (esv >= es[n - 1]) return { size, wall, k: invert(LV_K.slice(0, n), es.slice(0, n), esv), esSize: size };
  // a smaller LV at end-systole: the ESV at that contraction by size weight
  const col = LV_SZ.map((_, i) => at(i, n - 1));
  return { size, wall, k: LV_K[n - 1], esSize: Math.min(size, invert(LV_SZ, col, esv)) };
}

/**
 * The dx_lvSize weight that gives heart key's LV the fraction ratio of its own EDV, with its own
 * wall (stress.js: the smaller cavity with dobutamine).
 */
export function lvSizeFor(heart, ratio) {
  const T = LV[heart] || LV.normal, own = LV_WL.indexOf(0);
  const col = T.ed.map((row) => row[own]);
  return invert(LV_SZ, col, ratio * col[LV_SZ.indexOf(0)]);
}

