/**
 * The weights that show a mitral orifice of mva cm² by planimetry, with leaflets thickMm thick
 * at the tips, on heart key: { ms, thick, shift }. thick: what the leaflets add to the heart's
 * own (held to 0 to 5 mm); ms: from the area table at that thickness, made monotone (each area
 * the smallest so far) and held to its range, so an area above the heart's own opening shows
 * the open valve and one below the table's end shows that end; shift: the short axis at the
 * mitral valve moved to the tips.
 */
export function msWeights(heart, mva, thickMm) {
  const T = MSV[heart] || MSV.normal;
  const thick = Math.min(MS_TH[MS_TH.length - 1], Math.max(0, thickMm - T.own));
  const [i, t] = cell(MS_TH, thick);
  let lo = Infinity;
  const area = MS_W.map((_, k) => (lo = Math.min(lo, lerp(T.area[i][k], T.area[i + 1][k], t))));
  const ms = invert(MS_W, area, mva);
  const [j, u] = cell(MS_W, ms);
  const at = (r) => lerp(T.shift[r][j], T.shift[r][j + 1], u);
  return { ms, thick, shift: lerp(at(i), at(i + 1), t) };
}
/** The mitral orifice (cm²) that the weights of msWeights show on heart key. */
export function msArea(heart, ms, thick) {
  const T = MSV[heart] || MSV.normal, [i, t] = cell(MS_TH, thick), [j, u] = cell(MS_W, ms);
  const at = (r) => lerp(T.area[r][j], T.area[r][j + 1], u);
  return lerp(at(i), at(i + 1), t);
}
/** The leaflets' own thickness near the tips (mm) on heart key. */
export const mvOwnThick = (heart) => (MSV[heart] || MSV.normal).own;

