/**
 * The weights that show an aortic orifice of ava cm² by planimetry, with cusps cuspMm thick, on
 * heart key: { as, thick, shift }, as msWeights does for the mitral valve: thick, what the cusps
 * add to the heart's own (0 to 4 mm); as, from the area table at that thickness, made monotone
 * and held to its range; shift, the short axis at the aortic valve moved to the cusp tips.
 */
export function asWeights(heart, ava, cuspMm) {
  const T = ASV[heart] || ASV.normal;
  const thick = Math.min(AS_TH[AS_TH.length - 1], Math.max(0, cuspMm - T.own));
  const [i, t] = cell(AS_TH, thick);
  let lo = Infinity;
  const area = AS_W.map((_, k) => (lo = Math.min(lo, lerp(T.area[i][k], T.area[i + 1][k], t))));
  const w = invert(AS_W, area, ava);
  const [j, u] = cell(AS_W, w);
  const at = (r) => lerp(T.shift[r][j], T.shift[r][j + 1], u);
  return { as: w, thick, shift: lerp(at(i), at(i + 1), t) };
}
/** The aortic orifice (cm²) that the weights of asWeights show on heart key. */
export function asArea(heart, w, thick) {
  const T = ASV[heart] || ASV.normal, [i, t] = cell(AS_TH, thick), [j, u] = cell(AS_W, w);
  const at = (r) => lerp(T.area[r][j], T.area[r][j + 1], u);
  return lerp(at(i), at(i + 1), t);
}
/** The cusps' own thickness (mm) on heart key. */
export const avOwnThick = (heart) => (ASV[heart] || ASV.normal).own;

// Foreshortening (chapter 09): the fraction of the traced length lost at end-diastole against the
// probe's offset off the plane (cm, echo.js setFore), by LV size weight, on the normal heart.
const FORE_SZ = [-0.6, 0, 0.5, 1, 1.5];
const FORE_D = [0, -0.5, -1, -1.5, -2, -2.5, -3, -3.5, -4, -5, -6];
const FORE = {
  a4c: [[0, 0.0347, 0.0968, 0.1702, 0.272, 0.3844, 0.4678, 0.5264, 0.5745, 0.24, 0.2513], [0, 0.0202, 0.0546, 0.102, 0.1561, 0.2145, 0.2758, 0.3416, 0.3922, 0.4767, 0.5258], [0, 0.0123, 0.0358, 0.0665, 0.1066, 0.1517, 0.1975, 0.2372, 0.2784, 0.3558, 0.4094], [0, 0.0078, 0.0248, 0.0476, 0.0746, 0.1071, 0.1421, 0.1803, 0.2126, 0.2659, 0.3151], [0, 0.0055, 0.0181, 0.0359, 0.057, 0.0785, 0.1047, 0.1318, 0.1606, 0.2131, 0.2486]],
  a2c: [[0, 0.0349, 0.0961, 0.1695, 0.2633, 0.3597, 0.4438, 0.5101, 0.5652, 0.3932, 0.4148], [0, 0.0187, 0.054, 0.1005, 0.1556, 0.2143, 0.2704, 0.3242, 0.3739, 0.4547, 0.5154], [0, 0.0118, 0.0355, 0.0677, 0.1044, 0.1505, 0.1951, 0.2349, 0.2721, 0.333, 0.3805], [0, 0.0076, 0.0246, 0.0468, 0.0724, 0.1023, 0.1366, 0.1721, 0.2037, 0.2848, 0.2809], [0, 0.0055, 0.0179, 0.0341, 0.0529, 0.0727, 0.0956, 0.1185, 0.1438, 0.2266, 0.2079]],
};
/** cm the probe sits off the plane of view key (a4c, a2c) so that the traced LV is fraction f shorter, at size weight size. */
export function foreOffset(view, f, size = 0) {
  if (!(f > 0)) return 0;
  const T = FORE[view] || FORE.a4c;
  const [i, t] = cell(FORE_SZ, size);
  const row = T[i].map((v, j) => lerp(v, T[i + 1][j], t));
  let n = 1;
  while (n < row.length && row[n] > row[n - 1]) n++;
  return invert(FORE_D.slice(0, n), row.slice(0, n), f);
}

// ---------------------------------------------------------------- the right ventricle (rv.js)
// rvThick (phenomesh.js DISEASE) on the RV-focused four-chamber view at end-diastole: the RV free
// wall's thickness (mm) on the line of the RV basal diameter, linear in the weight on every heart.
// own: at weight 0, the mean of rvGrow 0 and 1 (rvGrow changes it by less than 0.2 mm); per: mm
// per unit of weight. The RV basal diameter grows by less than 0.1 cm at weight 1.
const RVW = {
  normal: { own: 3.55, per: 8.77 },
  amyloid: { own: 7.49, per: 9.0 },
  icm: { own: 3.19, per: 8.85 },
  barlow: { own: 3.3, per: 8.87 },
  bav: { own: 3.51, per: 9.1 },
};
/** The RV free wall's own thickness (mm) on heart key. */
export const rvWallOwn = (heart) => (RVW[heart] || RVW.normal).own;
/** The rvThick weight whose RV free wall is mm thick on heart key; a thinner wall than the heart's own thins it, to 2.6 mm less. */
export function rvThickOf(heart, mm) {
  const T = RVW[heart] || RVW.normal;
  return Math.max(-0.3, (mm - T.own) / T.per);
}
