/** The RV on the image under acute PE on heart key at slider position s: { fac, base, mid, apex } (%, mm). */
export function rvPeAt(heart, s) {
  const T = RV_PE[heart] || RV_PE.normal, n = T.length - 1, x = Math.min(n, Math.max(0, s * n)), i = Math.min(n - 1, Math.floor(x));
  const at = (k) => lerp(T[i][k], T[i + 1][k], x - i);
  return { fac: at(0), base: at(1), mid: at(2), apex: at(3) };
}
